    monitorar: sim(pick(r, ['Monitorar Custo']), true),
    pagina: dig(pick(r, ['ID da Página', 'ID da Pagina'])),
    ig_id: dig(pick(r, ['ID Instagram', 'ID do Instagram'])),
    ig_user: pick(r, ['Instagram (usuário)', 'Usuário do Instagram', 'Instagram']).replace(/^@/, ''),
    whatsapp_campanha: jid(pick(r, ['WhatsApp da Campanha', 'WhatsApp'])),
