  });
}

const sd = $getWorkflowStaticData('global');
sd.pausadas = sd.pausadas || {};
const agoraMs = Date.now();
for (const [id, p] of Object.entries(sd.pausadas)) if (!p || agoraMs - (p.ts || 0) > 8 * 86400000) delete sd.pausadas[id];
const limite = $now.minus({ days: 7 });
const logs = $input.all().map(i => i.json || {})
  .filter(l => !l.error && dig(pick(l, ['ID Campanha'])) && n_(pick(l, ['Status'])) === 'pausada')
  .filter(l => { const d = DateTime.fromFormat(pick(l, ['Data']), 'dd/MM/yyyy HH:mm', { zone: $now.zoneName }); return !d.isValid || d >= limite; });
sd.exec_seg = { [String($execution.id)]: {} };
const out = []; const semReativar = []; const contasAtivas = new Set(clientes.map(c => c.conta));
for (const c of clientes) {
  const mapa = new Map();
  for (const l of logs) {
    if (dig(pick(l, ['ID da Conta'])) !== c.conta) continue;
    const id = dig(pick(l, ['ID Campanha']));
    const prev = mapa.get(id);
    mapa.set(id, { id, nome: pick(l, ['Nome Campanha']) || (prev && prev.nome) || id, rows: [...(prev ? prev.rows : []), l.row_number].filter(Boolean) });
  }
  for (const [id, p] of Object.entries(sd.pausadas)) {
    if (String(p.conta) !== c.conta || mapa.has(id)) continue;
    mapa.set(id, { id, nome: p.nome || id, rows: [] });
  }
  if (!mapa.size) continue;
  if (!c.reativar) { semReativar.push(`${c.cliente} (${mapa.size})`); continue; }
  out.push({ json: { ...c, total: mapa.size, campanhas: [...mapa.values()] } });
}
const orfas = new Set([...logs.map(l => dig(pick(l, ['ID da Conta']))), ...Object.values(sd.pausadas).map(p => String(p.conta))].filter(c => c && !contasAtivas.has(c)));
if (!out.length) return [{ json: { vazio: true, sem_reativar: semReativar.join(', '), orfas: [...orfas].join(', '), total_logs: logs.length } }];
return out;

const errTxt = e => { if (e && typeof e === 'object') e = e.message || e.error_user_msg || e.description || JSON.stringify(e); return String(e ?? '').slice(0, 300); };

const src = $('Separar Campanhas (Seg)').item.json;
