return { json: {
  rows: src.campanhas.rows || [],
  'Status': ok ? 'Reativada' : 'Falha ao reativar',
  'Reativada em': ok ? $now.toFormat('dd/MM/yyyy HH:mm') : '',
  'Erro': ok ? '' : errTxt(r.error ?? JSON.stringify(r)),
  nome_campanha: src.campanhas.nome,
  id_campanha: src.campanhas.id
} };

const linhas = [];
for (const it of $input.all()) {
