  for (const rn of (j.rows || [])) linhas.push({ json: { row_number: rn, 'Status': j['Status'], 'Reativada em': j['Reativada em'], 'Erro': j['Erro'] } });
}
return linhas.length ? linhas : [{ json: { sem_linha: true } }];

const cli = $('Loop Clientes (Seg)').first().json;
