const itens = $('Montar Resultado (Seg)').all().map(i => i.json);
const ok = itens.filter(i => i['Status'] === 'Reativada');
const falhas = itens.filter(i => i['Status'] !== 'Reativada');
const logErros = $input.all().filter(i => i.json && i.json.error).length;
const nome = cli.cliente;
const mensagem = `Bom dia! ☀️\n\nPassando para avisar que as campanhas da conta *${nome}* foram *reativadas* e já estão voltando a ser veiculadas. 🚀\n\n📊 Campanhas reativadas: *${ok.length}*\n\nQualquer dúvida, é só chamar!\n\n— Equipe Konext`;
let alerta = '';
if (falhas.length || logErros || (ok.length && !cli.destino)) {
  alerta = `⚠️ *Atenção — Reativação de segunda*\n\nCliente: *${nome}*\nConta: ${cli.conta}\n✅ Reativadas: ${ok.length}\n❌ Falhas: ${falhas.length}`;
  if (falhas.length) alerta += '\n\n' + falhas.slice(0, 5).map(f => `• ${f.nome_campanha} (${f.id_campanha}): ${f['Erro']}`).join('\n');
  if (logErros) alerta += `\n\n📝 ${logErros} linha(s) da aba "Campanhas Pausadas" não foram atualizadas.`;
  if (ok.length && !cli.destino) alerta += '\n\n📵 Cliente sem grupo e sem "Contato do cliente" na Planilha Geral: *não foi avisado*.';
  if (falhas.length) alerta += '\n\nReative manualmente no Gerenciador de Anúncios.';
}
const envios = [];
