});
const sd = $getWorkflowStaticData('global'); const ek = String($execution.id);
const rec = ((sd.exec_seg || {})[ek] || {})[res.conta];
if (rec) { rec.aviso = avisoCliente; if (falhas.length) rec.obs = [rec.obs, 'Falha no WhatsApp'].filter(Boolean).join(' | '); }
const alerta = falhas.length ? `⚠️ *Falha ao enviar WhatsApp (Segunda)*\n\nCliente: *${res.cliente}*\n${falhas.join('\n')}\n\nAs campanhas foram reativadas normalmente.` : '';
return [{ json: { alerta } }];
